SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS vocations(code VARCHAR(24) PRIMARY KEY,name VARCHAR(40) NOT NULL,description VARCHAR(255) NOT NULL,base_health SMALLINT UNSIGNED NOT NULL,base_mana SMALLINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS maps(code VARCHAR(40) PRIMARY KEY,name VARCHAR(80) NOT NULL,width SMALLINT UNSIGNED NOT NULL,height SMALLINT UNSIGNED NOT NULL,recommended_level TINYINT UNSIGNED NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS characters(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(20) NOT NULL UNIQUE,vocation_code VARCHAR(24) NOT NULL,level INT UNSIGNED NOT NULL DEFAULT 1,experience BIGINT UNSIGNED NOT NULL DEFAULT 0,health INT UNSIGNED NOT NULL DEFAULT 100,mana INT UNSIGNED NOT NULL DEFAULT 50,map_code VARCHAR(40) NOT NULL DEFAULT 'elarion',tile_x SMALLINT UNSIGNED NOT NULL DEFAULT 8,tile_y SMALLINT UNSIGNED NOT NULL DEFAULT 8,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_char_user(user_id),KEY idx_char_rank(level,experience),CONSTRAINT fk_char_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_char_vocation FOREIGN KEY(vocation_code) REFERENCES vocations(code),CONSTRAINT fk_char_map FOREIGN KEY(map_code) REFERENCES maps(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS world_creatures(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,map_code VARCHAR(40) NOT NULL,code VARCHAR(40) NOT NULL,name VARCHAR(60) NOT NULL,tile_x SMALLINT UNSIGNED NOT NULL,tile_y SMALLINT UNSIGNED NOT NULL,level TINYINT UNSIGNED NOT NULL DEFAULT 1,health SMALLINT UNSIGNED NOT NULL,max_health SMALLINT UNSIGNED NOT NULL,experience_reward SMALLINT UNSIGNED NOT NULL DEFAULT 10,UNIQUE KEY uq_creature_map_code(map_code,code),KEY idx_creature_map_position(map_code,tile_x,tile_y),CONSTRAINT fk_creature_map FOREIGN KEY(map_code) REFERENCES maps(code) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS world_npcs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,map_code VARCHAR(40) NOT NULL,code VARCHAR(40) NOT NULL,name VARCHAR(60) NOT NULL,tile_x SMALLINT UNSIGNED NOT NULL,tile_y SMALLINT UNSIGNED NOT NULL,dialogue VARCHAR(255) NOT NULL,UNIQUE KEY uq_npc_map_code(map_code,code),CONSTRAINT fk_npc_map FOREIGN KEY(map_code) REFERENCES maps(code) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS quests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,npc_code VARCHAR(40) NOT NULL,title VARCHAR(100) NOT NULL,description VARCHAR(255) NOT NULL,target_creature_code VARCHAR(40) NOT NULL,target_count SMALLINT UNSIGNED NOT NULL DEFAULT 1,reward_experience INT UNSIGNED NOT NULL DEFAULT 25) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS character_quests(character_id BIGINT UNSIGNED NOT NULL,quest_id BIGINT UNSIGNED NOT NULL,status ENUM('accepted','completed','claimed') NOT NULL DEFAULT 'accepted',progress SMALLINT UNSIGNED NOT NULL DEFAULT 0,accepted_at DATETIME NOT NULL,completed_at DATETIME NULL,claimed_at DATETIME NULL,PRIMARY KEY(character_id,quest_id),CONSTRAINT fk_character_quest_character FOREIGN KEY(character_id) REFERENCES characters(id) ON DELETE CASCADE,CONSTRAINT fk_character_quest_quest FOREIGN KEY(quest_id) REFERENCES quests(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
